#!/usr/bin/env bash
# tests/rawdofmt_probe.sh - builds tests/rawdofmt_probe.s (CLI executable, case table generated by
# tests/rawdofmt_check.py), writes it with a startup-sequence that runs it on a bootable OFS disk, boots the disk in
# an Amiberry session, reads the probe's output buffer through gdb (its bounds are printed on the serial port before
# "RDP fin") into <out_dir>/rawdofmt.txt and checks it with tests/rawdofmt_check.py (one PASS/FAIL line per vector).
# Expected values: docs/analysis/exec-rawdofmt-v34.md §7, with this ROM's deliberate differences (docs/PLAN.md,
# rank 11).
#
# Usage: tests/rawdofmt_probe.sh <out_dir> [rom=build/kick13-prod.rom]
# The Commodore ROM is refused by amiberry-session unless RDP_ANALYSIS=1 (analysis agent only, see CLAUDE.md); the
# output is then checked against the 1.3 values (check13).
set -u
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
OUT="${1:?out_dir}"; ROM="${2:-$ROOT/build/kick13-prod.rom}"
A="$ROOT/.claude/skills/amiberry/scripts/amiberry-session"
mkdir -p "$OUT"
python3 -I "$ROOT/tests/rawdofmt_check.py" gen "$OUT/rawdofmt_cases.i" || exit 2
vasmm68k_mot -Fhunkexe -kick1hunks -nosym -m68000 -quiet -I "$OUT" -o "$OUT/rawdofmt_probe" \
  "$ROOT/tests/rawdofmt_probe.s" || exit 2
printf 'df0:rawdofmt_probe\n' > "$OUT/startup"
ADF="$OUT/rawdofmt_$$.adf"; rm -f "$ADF"
xdftool "$ADF" create + format Probe ofs + boot install + makedir s + write "$OUT/startup" s/startup-sequence \
  + write "$OUT/rawdofmt_probe" rawdofmt_probe >/dev/null || { echo "xdftool failed"; exit 2; }
NAME="${RDP_NAME:-rdp$$}"
EXTRA=(); DIR="$ROOT/build/amiberry/sessions/$NAME"; MODE=check
[ "${RDP_ANALYSIS:-0}" = 1 ] && { EXTRA=(--analysis); DIR="$ROOT/build/amiberry/analysis/$NAME"; MODE=check13; }
"$A" start --name "$NAME" --rom "$ROM" --adf "$ADF" --timeout 120 "${EXTRA[@]}" || exit 2
"$A" wait-serial "$NAME" "RDP fin" 600; RC=$?
if [ $RC = 0 ]; then
  BUF=$(tr -d '\r' < "$DIR/serial.log" | grep -a -m1 -o 'RDP buf=[0-9A-F]\{8\} end=[0-9A-F]\{8\}$')
  S=${BUF#RDP buf=}; S=${S%% *}; E=${BUF##*end=}
  [ -n "$BUF" ] && "$A" gdb "$NAME" -ex "dump binary memory $OUT/rawdofmt.bin 0x$S 0x$E" >/dev/null
  tr -d '\r' < "$OUT/rawdofmt.bin" | sed -n '/^RDP debut/,/^RDP fin/p' > "$OUT/rawdofmt.txt"
fi
"$A" stop "$NAME" >/dev/null
[ $RC = 0 ] || { echo "no RDP fin (timeout)"; exit 1; }
[ -s "$OUT/rawdofmt.txt" ] || { echo "output buffer not read"; exit 1; }
python3 -I "$ROOT/tests/rawdofmt_check.py" $MODE "$OUT/rawdofmt.txt" > "$OUT/rawdofmt_check.txt"; RC=$?
grep -v '^PASS' "$OUT/rawdofmt_check.txt"
exit $RC
